import { render, screen, fireEvent } from '@testing-library/react'
import { expect, test } from 'vitest'
import { ErrorBoundary } from './ErrorBoundary'

let shouldThrow = true
function Flaky() {
  if (shouldThrow) throw new Error('boom')
  return <p>ok</p>
}
const quiet = (fn) => { const e = console.error; console.error = () => {}; try { fn() } finally { console.error = e } }

test('renders children when fine', () => {
  shouldThrow = false
  render(<ErrorBoundary fallback={() => <p>fallback</p>}><Flaky /></ErrorBoundary>)
  expect(screen.getByText('ok')).toBeTruthy()
})

test('shows the fallback and reports the error', () => {
  shouldThrow = true
  const errors = []
  quiet(() => render(<ErrorBoundary onError={(e) => errors.push(e.message)} fallback={(e) => <p>failed: {e.message}</p>}><Flaky /></ErrorBoundary>))
  expect(screen.getByText('failed: boom')).toBeTruthy()
  expect(errors).toEqual(['boom'])
})

test('reset renders the children again', () => {
  shouldThrow = true
  quiet(() => render(<ErrorBoundary fallback={(e, reset) => <button onClick={reset}>retry</button>}><Flaky /></ErrorBoundary>))
  shouldThrow = false
  fireEvent.click(screen.getByText('retry'))
  expect(screen.getByText('ok')).toBeTruthy()
})

