import { useImperativeHandle, useRef } from 'react'

export function SearchInput({ ref, onClear, ...props }) {
  const inp = useRef(null)
  useImperativeHandle(ref, () => ({
    focus: () => inp.current.focus(),
    clear: () => { inp.current.value = ''; onClear?.() },
  }))
  return <input ref={inp} aria-label="search" {...props} />
}

