import { createContext, useContext, useState } from 'react'

const Root = createContext(null)
const ItemCtx = createContext(null)

export function Accordion({ children }) {
  const [openId, setOpenId] = useState(null)
  return <Root value={{ openId, setOpenId }}><div>{children}</div></Root>
}
Accordion.Item = function Item({ id, children }) {
  return <ItemCtx value={id}><section>{children}</section></ItemCtx>
}
Accordion.Header = function Header({ children }) {
  const { openId, setOpenId } = useContext(Root)
  const id = useContext(ItemCtx)
  const open = openId === id
  return <button aria-expanded={open} onClick={() => setOpenId(open ? null : id)}>{children}</button>
}
Accordion.Panel = function Panel({ children }) {
  const { openId } = useContext(Root)
  return openId === useContext(ItemCtx) ? <div role="region">{children}</div> : null
}

