import { createContext, useContext, useEffect, useState } from 'react'

const Api = createContext(null)

export function ApiProvider({ client, children }) {
  return <Api value={client}>{children}</Api>
}

export function useApi() {
  const c = useContext(Api)
  if (!c) throw new Error('useApi must be used inside ApiProvider')
  return c
}

export function UserName({ id }) {
  const api = useApi()
  const [user, setUser] = useState(null)
  useEffect(() => {
    let ignore = false
    api.getUser(id).then((u) => { if (!ignore) setUser(u) })
    return () => { ignore = true }
  }, [api, id])
  return <p>{user ? user.name : 'Loading…'}</p>
}

