export function withAuth(Component, { role } = {}) {
  function Guarded(props) {
    if (!props.user) return <p>Please log in</p>
    if (role && props.user.role !== role) return <p>Forbidden</p>
    return <Component {...props} />
  }
  Guarded.displayName = `withAuth(${Component.displayName || Component.name})`
  return Guarded
}

